// Terminal / Native Shell — Real CLI Terminal Window
export const ShellLogo: React.FC<LogoProps> = ({ className = 'w-5 h-5', size }) => (
  <svg
    viewBox="0 0 24 24"
    width={size}
    height={size}
    className={className}
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-label="Terminal"
  >
    <rect x="2" y="4" width="20" height="16" rx="3" />
    <path d="M6 9l3 3-3 3" />
    <line x1="12" y1="15" x2="16" y2="15" />
  </svg>
);

export function getAgentLogo(agentId: string, className = 'w-5 h-5'): React.ReactElement {
  switch (agentId) {
    case 'claude-code':
      return <ClaudeLogo className={className} />;
    case 'gemini':
      return <GeminiLogo className={className} />;
    case 'codex':
      return <OpenAILogo className={className} />;
    case 'grok':
      return <GrokLogo className={className} />;
    case 'deepseek':
      return <DeepSeekLogo className={className} />;
    case 'antigravity':
      return <AntigravityLogo className={className} />;
    case 'kimi':
      return <KimiLogo className={className} />;
    case 'qwen':
      return <QwenLogo className={className} />;
    case 'aider':
      return <AiderLogo className={className} />;
    case 'openhands':
      return <OpenHandsLogo className={className} />;
    case 'ollama':
      return <OllamaLogo className={className} />;
    case 'goose':
      return <GooseLogo className={className} />;
    case 'cline':
      return <ClineLogo className={className} />;
    case 'shell':
    default:
      return <ShellLogo className={className} />;
  }
}

